(5574049, 806878, 100301, '<td valign="top">reminds me of silver creek falls in oregon</td>', 'reminds me of silver creek falls in oregon', '2009-07-15 01:18:31.000000', NULL, 1),
(5574108, 807207, 45475, '<td valign="top">Gorgeous exposure and nice drama in the sea.</td>', 'Gorgeous exposure and nice drama in the sea.', '2009-07-15 01:37:38.000000', NULL, 1),
(5574115, 807299, 45475, '<td valign="top">Sky colour looks a tad oversaturated but otherwise, awesome!</td>', 'Sky colour looks a tad oversaturated but otherwise, awesome!', '2009-07-15 01:40:37.000000', NULL, 1),
(5574120, 807304, 45475, '<td valign="top">Oooh... so lucky you have an <strike>egret</strike> heron (&lt;-duh) in this shot, otherwise I would have rolled my eyes and moved on ;)<br/><br/><i>Message edited by author 2009-07-22 05:38:49.</i></td>', 'Oooh... so lucky you have an egret heron (<-duh) in this shot, otherwise I would have rolled my eyes and moved on ;)', '2009-07-15 01:42:58.000000', '2009-07-22 06:38:49.000000', 1),
(5574129, 807206, 45475, '<td valign="top">Oh dear... problem with noise? Fabulous shot, though far too much NI has destroyed texture.</td>', 'Oh dear... problem with noise? Fabulous shot, though far too much NI has destroyed texture.', '2009-07-15 01:47:42.000000', NULL, 1),
(5574149, 806763, 45475, '<td valign="top">I keep telling people, have a slingshot handy. It''s the only way you''ll get folk to move out of your scene.<br/> <br/>This place is spectacular, unspoiled and unpretentious, as is your shot of it! Congrats :)</td>', 'I keep telling people, have a slingshot handy. It''s the only way you''ll get folk to move out of your scene. This place is spectacular, unspoiled and unpretentious, as is your shot of it! Congrats :)', '2009-07-15 01:53:15.000000', NULL, 1),
