(5574315, 807154, 108525, '<td valign="top">OOF</td>', 'OOF', '2009-07-15 03:08:36.000000', NULL, 1),
(5574492, 807054, 54446, '<td valign="top">Looks like Long''s to me.  Nice perspective and fine detail.  From Chasm Lake, I presume?  "10"</td>', 'Looks like Long''s to me.  Nice perspective and fine detail.  From Chasm Lake, I presume?  "10"', '2009-07-15 07:45:12.000000', NULL, 1),
(5574494, 806716, 54446, '<td valign="top">Excellent entry.  Would be better without the man, but I''ll admit he offers a scale measuring tool.</td>', 'Excellent entry.  Would be better without the man, but I''ll admit he offers a scale measuring tool.', '2009-07-15 07:46:14.000000', NULL, 1),
(5574497, 807125, 54446, '<td valign="top">Excellent exposure.  The person is a distraction, but does provide a scale measure.  I think these formations are mostly wind carved, although most people think it had to be water erosion. 9</td>', 'Excellent exposure.  The person is a distraction, but does provide a scale measure.  I think these formations are mostly wind carved, although most people think it had to be water erosion. 9', '2009-07-15 07:50:40.000000', NULL, 1),
(5574577, 806763, 43774, '<td valign="top">Lovely photo, impressive sea stack. Your horizon isn''t straight though.</td>', 'Lovely photo, impressive sea stack. Your horizon isn''t straight though.', '2009-07-15 09:16:25.000000', NULL, 1),
(5574737, 807272, 108385, '<td valign="top">I really like this photo as it makes me wonder what is really going on. What is the liquid? How was the movements created? Where does the light come from? A photo that appeals to my imagination.</td>', 'I really like this photo as it makes me wonder what is really going on. What is the liquid? How was the movements created? Where does the light come from? A photo that appeals to my imagination.', '2009-07-15 10:09:25.000000', NULL, 1),
(5574860, 806763, 26318, '<td valign="top">This image is a great piece of geology, I have seen some similar ones along the Oregon coast.  The only thing that I would change is the one person in the picture... now that I see him, I think it takes away from the photo where he is at.</td>', 'This image is a great piece of geology, I have seen some similar ones along the Oregon coast.  The only thing that I would change is the one person in the picture... now that I see him, I think it takes away from the photo where he is at.', '2009-07-15 11:31:00.000000', NULL, 1),
(5574861, 807219, 26318, '<td valign="top">I have always loved this location and hope one day to get there myself.  It really does tell the stories of the sandstone...</td>', 'I have always loved this location and hope one day to get there myself.  It really does tell the stories of the sandstone...', '2009-07-15 11:32:03.000000', NULL, 1),
(5574863, 806987, 26318, '<td valign="top">I think the one thing that this image is missing is some sense of scale...  I can''t really pick out one thing that tells me how bit the rock face is.</td>', 'I think the one thing that this image is missing is some sense of scale...  I can''t really pick out one thing that tells me how bit the rock face is.', '2009-07-15 11:34:09.000000', NULL, 1),
(5574864, 807203, 26318, '<td valign="top">Great shot, and I like how this one is a bit different in lighting and perspective on the location.  I hope one day to get there and take some photos myself.</td>', 'Great shot, and I like how this one is a bit different in lighting and perspective on the location.  I hope one day to get there and take some photos myself.', '2009-07-15 11:35:53.000000', NULL, 1),
(5574867, 807164, 26318, '<td valign="top">Great view of the landscape.  The growth of trees and greenery around the rocks really gives me a feel of the age.   Well done.</td>', 'Great view of the landscape.  The growth of trees and greenery around the rocks really gives me a feel of the age.   Well done.', '2009-07-15 11:37:31.000000', NULL, 1),
