(5575713, 807166, 37845, '<td valign="top">This place looks really cool... like the kind of place you go when you want to be left alone. Nice and moody.</td>', 'This place looks really cool... like the kind of place you go when you want to be left alone. Nice and moody.', '2009-07-15 22:53:08.000000', NULL, 1),
(5575714, 806977, 37845, '<td valign="top">I have no idea what I am looking at, but it is definitely geologic :) One critique though... the shadows created by the flash take away from the photo a bit.</td>', 'I have no idea what I am looking at, but it is definitely geologic :) One critique though... the shadows created by the flash take away from the photo a bit.', '2009-07-15 22:54:01.000000', NULL, 1),
