(5575739, 806761, 37845, '<td valign="top">This scene reminds me of northern ontario.... looks like the Canadian shield. Nice photo.</td>', 'This scene reminds me of northern ontario.... looks like the Canadian shield. Nice photo.', '2009-07-15 23:12:06.000000', NULL, 1),
(5575748, 807347, 2170, '<td valign="top">too dark :(</td>', 'too dark :(', '2009-07-15 23:14:59.000000', NULL, 1),
(5575762, 807203, 80859, '<td valign="top">you really can''t go wrong at antelope canyon. i knew there would be a few.  this is a really nice one.  nice perspective and curves.  very well done</td>', 'you really can''t go wrong at antelope canyon. i knew there would be a few.  this is a really nice one.  nice perspective and curves.  very well done', '2009-07-15 23:28:56.000000', NULL, 1),
(5575770, 807353, 37845, '<td valign="top">Your choice of aperature here, giving the really shallow DOF is what makes this shot. This rock has a lot of character, and good texture. Nicely captured.</td>', 'Your choice of aperature here, giving the really shallow DOF is what makes this shot. This rock has a lot of character, and good texture. Nicely captured.', '2009-07-15 23:35:55.000000', NULL, 1),
(5575772, 806695, 37845, '<td valign="top">Minimilist in nature... works well for this shot.</td>', 'Minimilist in nature... works well for this shot.', '2009-07-15 23:36:20.000000', NULL, 1),
(5575779, 807022, 80859, '<td valign="top">that, to me, is more like ''geography'' than geology. i like it, though and it''s one of the more unique photos in the challenge as it isn''t a physical illustration (ie rocks, mountains, etc...) of the topic</td>', 'that, to me, is more like ''geography'' than geology. i like it, though and it''s one of the more unique photos in the challenge as it isn''t a physical illustration (ie rocks, mountains, etc...) of the topic', '2009-07-15 23:49:45.000000', NULL, 1),
